<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('inventory.view');
$q=trim((string)($_GET['q']??''));$category=(int)($_GET['category']??0);$where=['p.status="active"','p.track_stock=1'];$params=[];if($q!==''){$where[]='(p.name LIKE :q OR p.sku LIKE :q OR p.barcode LIKE :q)';$params[':q']='%'.$q.'%';}if($category>0){$where[]='p.category_id=:category';$params[':category']=$category;}$ws=implode(' AND ',$where);$st=db()->prepare("SELECT p.id,p.name,p.sku,p.current_stock,p.minimum_stock,p.average_cost,p.selling_price,c.name category_name,u.short_name FROM products p INNER JOIN categories c ON c.id=p.category_id INNER JOIN units u ON u.id=p.unit_id WHERE $ws ORDER BY (p.current_stock<=p.minimum_stock) DESC,p.name LIMIT 200");$st->execute($params);$products=$st->fetchAll();$categories=db()->query('SELECT id,name FROM categories WHERE status="active" ORDER BY name')->fetchAll();$summary=db()->query('SELECT COUNT(*) products,COALESCE(SUM(current_stock),0) units_total,COALESCE(SUM(current_stock*average_cost),0) value,SUM(current_stock<=minimum_stock) low_count FROM products WHERE status="active" AND track_stock=1')->fetch()?:[];
$pageTitle='Inventory';$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><?php require BASE_PATH.'/includes/alerts.php';?><div class="page-toolbar"><div><span class="eyebrow">Stock control</span><h2>Inventory</h2><p>Live stock balances backed by the stock movement ledger.</p></div><div class="toolbar-actions"><?php if(user_can('inventory.adjust')):?><a class="button button--secondary" href="<?=e(app_url('inventory/stock_adjustment'))?>">Stock adjustment</a><?php endif;?><a class="button button--primary" href="<?=e(app_url('inventory/stock_movements'))?>">Movement ledger</a></div></div>
<section class="mini-metric-grid"><article class="mini-metric"><span>Tracked products</span><strong><?=e((string)($summary['products']??0))?></strong></article><article class="mini-metric"><span>Stock value</span><strong><?=e(money($summary['value']??0))?></strong></article><article class="mini-metric"><span>Low / out</span><strong><?=e((string)($summary['low_count']??0))?></strong></article><article class="mini-metric"><span>Latest check</span><strong class="metric-text"><?=e(date('H:i'))?></strong></article></section>
<section class="panel-card table-panel"><form method="get" class="filter-bar"><div class="filter-search"><input name="q" value="<?=e($q)?>" placeholder="Search product, SKU or barcode"></div><select name="category"><option value="0">All categories</option><?php foreach($categories as$c):?><option value="<?=e((string)$c['id'])?>" <?=$category===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><button class="button button--secondary">Filter</button><a class="button button--ghost" href="<?=e(app_url('inventory/low_stock'))?>">Low stock</a></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Category</th><th>Current stock</th><th>Minimum</th><th>Avg. cost</th><th>Stock value</th><th></th></tr></thead><tbody><?php if(!$products):?><tr><td colspan="7"><div class="empty-state"><strong>No inventory products found</strong></div></td></tr><?php else:foreach($products as$p):$low=(float)$p['current_stock']<=(float)$p['minimum_stock'];?><tr><td><strong><?=e($p['name'])?></strong><small class="table-note"><?=e($p['sku'])?></small></td><td><?=e($p['category_name'])?></td><td><strong class="<?=$low?'text-warning':''?>"><?=e(format_quantity($p['current_stock']))?> <?=e($p['short_name'])?></strong></td><td><?=e(format_quantity($p['minimum_stock']))?> <?=e($p['short_name'])?></td><td><?=e(money($p['average_cost']))?></td><td><?=e(money((string)((float)$p['current_stock']*(float)$p['average_cost'])))?></td><td class="table-action-cell"><a class="table-action" href="<?=e(app_url('inventory/stock_history?product='.(int)$p['id']))?>">History</a></td></tr><?php endforeach;endif;?></tbody></table></div></section>
</main></div><?php require BASE_PATH.'/includes/footer.php';?>
